import datetime
import re

from ta_moler.events.egate.genericepcsim_lineevent import GenericEPCSIMLineEvent


class S1LinkDown(GenericEPCSIMLineEvent):
    """S1LinkDown event class."""

    # 10:08:26.617 ACR: MME-1: Multihoming peer address (10.10.31.1:36412[0]) on S1 link to eNB 1 is Down
    _re_detect_pattern = re.compile(r"S1 link to (?P<ENB>eNB \d+) is Down")

    def __init__(self, connection, till_occurs_times=-1, runner=None):
        """
        Event for 'Wait for response from ping.'.

        :param connection: moler connection to device, terminal when command is executed
        :param till_occurs_times: number of event occurrence
        :param runner: Runner to run event
        """
        super(S1LinkDown, self).__init__(
            connection=connection, runner=runner, till_occurs_times=till_occurs_times, detect_patterns=[S1LinkDown._re_detect_pattern], match="any"
        )


EVENT_OUTPUT = """
10:08:26.617 ACR: MME-1: Multihoming peer address (10.10.31.1:36412[0]) on S1 link to eNB 1 is Down
"""

EVENT_KWARGS = {"till_occurs_times": 1}

EVENT_RESULT = [
    {
        "line": "10:08:26.617 ACR: MME-1: Multihoming peer address (10.10.31.1:36412[0]) on S1 link to eNB 1 is Down",
        "groups": ("eNB 1",),
        "named_groups": {"ENB": "eNB 1"},
        "matched": "S1 link to eNB 1 is Down",
        "time": datetime.datetime.now(),
    }
]
